export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** `null` unless `userId` is currently away (per `startsAt`/`endsAt`) with a delegate named. */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<UserId | null> {
  const absence = await findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;
  return absence.startsAt <= at && at < absence.endsAt
    ? absence.delegateUserId
    : null;
}

/** Setting again replaces the previous row; the unique `(org_id, user_id)` index is the upsert key. */
export async function upsertAbsence(
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .run();
}

/** Drops delegation onto a removed member without touching the absence itself. */
export async function clearDelegateFor(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

